using System.Diagnostics;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
namespace VmWindowCapture;
static class Program {
 record WindowInfo(long Handle,int ProcessId,string Title,string? ProcessPath,int X,int Y,int Width,int Height,bool Minimized);
 [STAThread] static int Main(string[] args){Native.SetProcessDpiAwarenessContext(new IntPtr(-4));try{var windows=Windows();if(args.Length==1&&args[0]=="list"){Console.WriteLine(JsonSerializer.Serialize(windows,new JsonSerializerOptions{WriteIndented=true}));return 0;}if(args.Length==2&&args[0]=="restore"){long requested=long.Parse(args[1]);var restoreWindow=windows.SingleOrDefault(w=>w.Handle==requested)??throw new InvalidOperationException("Unknown VM window.");Native.ShowWindow(new IntPtr(requested),9);Console.WriteLine("Restored VisionMaster window "+requested);return 0;}if(args.Length==4&&args[0]=="double-click"){long requested=long.Parse(args[1]);var clickWindow=windows.SingleOrDefault(w=>w.Handle==requested)??throw new InvalidOperationException("Unknown VM window.");int x=int.Parse(args[2]),y=int.Parse(args[3]);if(clickWindow.Minimized||x<0||y<0||x>=clickWindow.Width||y>=clickWindow.Height)throw new ArgumentException("Invalid current screenshot coordinate.");var point=new Native.Point{X=clickWindow.X+x,Y=clickWindow.Y+y};if(!Native.ScreenToClient(new IntPtr(requested),ref point))throw new InvalidOperationException("Coordinate conversion failed.");var position=new IntPtr((point.Y<<16)|(point.X&0xffff));Native.SetForegroundWindow(new IntPtr(requested));foreach(var message in new uint[]{0x201,0x202,0x203,0x202})if(!Native.PostMessage(new IntPtr(requested),message,message is 0x201 or 0x203?new IntPtr(1):IntPtr.Zero,position))throw new InvalidOperationException("Window input request failed.");Console.WriteLine("Double-click requested for observed VM screenshot coordinate.");return 0;}if(args.Length==3&&args[0]=="wheel"){long handle=long.Parse(args[1]);var target=windows.Single(w=>w.Handle==handle);int delta=int.Parse(args[2]);if(target.Minimized||Math.Abs(delta)>2400)throw new ArgumentException("Invalid scroll request");int x=target.X+target.Width/2,y=target.Y+target.Height/2;Native.SetForegroundWindow(new IntPtr(handle));Native.SetCursorPos(x,y);if(Native.GetForegroundWindow()!=new IntPtr(handle))throw new InvalidOperationException("VM window must be foreground");Native.mouse_event(0x0800,0,0,unchecked((uint)delta),UIntPtr.Zero);Console.WriteLine("VM window scroll requested");return 0;}if(args.Length is not(3 or 4)||args[0]!="capture"){Console.Error.WriteLine("VmWindowCapture list | capture <returned-window-handle> <output.png> [print|visible]");return 2;}long id=long.Parse(args[1],System.Globalization.CultureInfo.InvariantCulture);var window=windows.SingleOrDefault(w=>w.Handle==id)??throw new InvalidOperationException("Handle is not a currently returned VisionMaster window.");if(window.Minimized||window.Width<=0||window.Height<=0)throw new InvalidOperationException("Target window is minimized or empty.");if((long)window.Width*window.Height>40000000)throw new InvalidOperationException("Capture exceeds size limit.");string method=args.Length==4?args[3]:"print";string output=Path.GetFullPath(args[2]);Directory.CreateDirectory(Path.GetDirectoryName(output)!);using var bitmap=new Bitmap(window.Width,window.Height,PixelFormat.Format32bppArgb);using(var graphics=Graphics.FromImage(bitmap)){if(method=="print"){graphics.Clear(Color.Black);var hdc=graphics.GetHdc();bool captured;try{captured=Native.PrintWindow(new IntPtr(id),hdc,2);}finally{graphics.ReleaseHdc(hdc);}if(!captured)throw new InvalidOperationException("PrintWindow failed; no screenshot saved.");}else if(method=="visible"){if(Native.GetForegroundWindow()!=new IntPtr(id))throw new InvalidOperationException("Visible capture requires this exact VM window to be foreground; no activation is performed.");graphics.CopyFromScreen(window.X,window.Y,0,0,bitmap.Size,CopyPixelOperation.SourceCopy);}else throw new ArgumentException("Unknown capture method.");}var colors=new HashSet<int>();for(int y=0;y<bitmap.Height;y+=Math.Max(1,bitmap.Height/30))for(int x=0;x<bitmap.Width;x+=Math.Max(1,bitmap.Width/30))colors.Add(bitmap.GetPixel(x,y).ToArgb()&0xffffff);if(colors.Count<3)throw new InvalidOperationException("Capture is blank or uniform; not accepted as VM evidence. Try visible mode after focusing VM.");bitmap.Save(output,ImageFormat.Png);File.WriteAllText(output+".json",JsonSerializer.Serialize(new{source="external native VisionMaster window",capturedAtUtc=DateTime.UtcNow,method,window,pixelFormat="32bppArgb",colorSampleCount=colors.Count,limitation=method=="print"?"Window rendering capture; GPU/native child surfaces require visual verification":"Visible desktop region; overlays or other windows may obscure it"},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(output);return 0;}catch(Exception ex){Console.Error.WriteLine(ex.Message);return 1;}}
 static List<WindowInfo> Windows(){var result=new List<WindowInfo>();Native.EnumWindows((handle,_)=>{if(!Native.IsWindowVisible(handle))return true;Native.GetWindowThreadProcessId(handle,out uint pid);try{using var process=Process.GetProcessById((int)pid);if(!string.Equals(process.ProcessName,"VisionMaster",StringComparison.OrdinalIgnoreCase)&&!string.Equals(process.ProcessName,"VisionEditor",StringComparison.OrdinalIgnoreCase)&&!string.Equals(process.ProcessName,"dotnet",StringComparison.OrdinalIgnoreCase))return true;string? path=null;try{path=process.MainModule?.FileName;}catch(System.ComponentModel.Win32Exception){}var title=new StringBuilder(1024);Native.GetWindowText(handle,title,title.Capacity);if(string.Equals(process.ProcessName,"dotnet",StringComparison.OrdinalIgnoreCase)&&title.ToString()!="VisionMaster")return true;if(!Native.GetWindowRect(handle,out var rect))return true;result.Add(new(handle.ToInt64(),(int)pid,title.ToString(),path,rect.Left,rect.Top,rect.Right-rect.Left,rect.Bottom-rect.Top,Native.IsIconic(handle)));}catch(ArgumentException){}return true;},IntPtr.Zero);return result;}
}
static class Native {
 [DllImport("user32.dll")] public static extern void mouse_event(uint flags,uint dx,uint dy,uint data,UIntPtr extra);
 [DllImport("user32.dll")] public static extern bool SetCursorPos(int x,int y);
 [StructLayout(LayoutKind.Sequential)]internal struct Point{public int X,Y;}
 [DllImport("user32.dll")]internal static extern bool ScreenToClient(IntPtr window,ref Point point);
 [DllImport("user32.dll")]internal static extern bool SetForegroundWindow(IntPtr window);
 [DllImport("user32.dll")]internal static extern bool PostMessage(IntPtr window,uint message,IntPtr wparam,IntPtr lparam);
 internal delegate bool EnumCallback(IntPtr window,IntPtr parameter);
 [StructLayout(LayoutKind.Sequential)]internal struct Rect{public int Left,Top,Right,Bottom;}
 [DllImport("user32.dll")]internal static extern bool EnumWindows(EnumCallback callback,IntPtr parameter);
 [DllImport("user32.dll")]internal static extern bool IsWindowVisible(IntPtr window);
 [DllImport("user32.dll")]internal static extern bool IsIconic(IntPtr window);
 [DllImport("user32.dll")]internal static extern uint GetWindowThreadProcessId(IntPtr window,out uint processId);
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]internal static extern int GetWindowText(IntPtr window,StringBuilder text,int count);
 [DllImport("user32.dll")]internal static extern bool GetWindowRect(IntPtr window,out Rect rectangle);
 [DllImport("user32.dll")]internal static extern bool PrintWindow(IntPtr window,IntPtr hdc,uint flags);
 [DllImport("user32.dll")]internal static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")]internal static extern bool ShowWindow(IntPtr window,int command);
 [DllImport("user32.dll")]internal static extern bool SetProcessDpiAwarenessContext(IntPtr context);
}




